};

pub fn recite(buffer: []u8, start_verse: u32, end_verse: u32) ![]const u8 {
    var pos: usize = 0;
    var first: bool = true;
    for (start_verse..end_verse + 1) |i| {
        const idx = i - 1;
        if (idx >= verse_data.len) return error.IndexOutOfBounds;
        const verse = verse_data[idx];

